parameters.functionScript:
function plain(x) {
  if (x === null || x === undefined) return x;
  if (Array.isArray(x)) return x.map(plain);
  if (typeof x === 'object') {
    if (typeof x.get === 'function' && x.data && typeof x.data === 'object') return plain(x.data);
    if (Array.isArray(x.items)) return plain(x.items);
    const out = {};
    for (const k of Object.keys(x)) out[k] = plain(x[k]);
    return out;
  }
  return x;
}
const rows = plain(Inputs.items) || [];
const lesson = rows[0];
if (!lesson) return;
Outputs.title = lesson.title || '';
Outputs.hook = lesson.hook || '';
Outputs.landing = lesson.landing || '';
Outputs.conceptId = lesson.conceptId || '';
Outputs.steps = lesson.steps || [];
Outputs.sections = lesson.sections || [];
Outputs.loaded();
